import PDFDocument from 'pdfkit';
import fs from 'fs';

const FONT_CANDIDATES = [
  // Liberation Sans — метрики Arial, шрифт бланка-образца (пакет fonts-liberation в Dockerfile)
  {
    regular: '/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf',
    bold: '/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf',
  },
  {
    regular: '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',
    bold: '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf',
  },
  {
    regular: '/usr/share/fonts/dejavu/DejaVuSans.ttf',
    bold: '/usr/share/fonts/dejavu/DejaVuSans-Bold.ttf',
  },
];

function resolveFonts(): { regular: string; bold: string } | null {
  for (const c of FONT_CANDIDATES) {
    if (fs.existsSync(c.regular) && fs.existsSync(c.bold)) return c;
  }
  return null;
}

// Логотип WeLANS (тёмный вариант для белого фона), data:image/png;base64
const LOGO_PNG_BASE64 =
  '"';


const MONTHS_NOM = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'];

// Системы налогообложения и ставки НДС — зеркало списков из RequisitesSettings.tsx
export const TAX_SYSTEMS: Record<string, string> = {
  osno: 'ОСНО',
  usn6: 'УСН 6%',
  usn15: 'УСН 15%',
  ausn8: 'АУСН 8%',
  ausn22: 'АУСН 22%',
  psn: 'ПСН',
  npd4: 'НПД 4%',
  npd6: 'НПД 6%',
  esxhn: 'ЕСХН',
};

const UNITS = ['', 'один', 'два', 'три', 'четыре', 'пять', 'шесть', 'семь', 'восемь', 'девять'];
const UNITS_F = ['', 'одна', 'две', 'три', 'четыре', 'пять', 'шесть', 'семь', 'восемь', 'девять'];
const TEENS = ['десять', 'одиннадцать', 'двенадцать', 'тринадцать', 'четырнадцать', 'пятнадцать', 'шестнадцать', 'семнадцать', 'восемнадцать', 'девятнадцать'];
const TENS = ['', '', 'двадцать', 'тридцать', 'сорок', 'пятьдесят', 'шестьдесят', 'семьдесят', 'восемьдесят', 'девяносто'];
const HUNDREDS = ['', 'сто', 'двести', 'триста', 'четыреста', 'пятьсот', 'шестьсот', 'семьсот', 'восемьсот', 'девятьсот'];

function three(n: number, feminine: boolean): string {
  const parts: string[] = [];
  const h = Math.floor(n / 100);
  const rem = n % 100;
  if (h) parts.push(HUNDREDS[h]);
  if (rem >= 10 && rem < 20) {
    parts.push(TEENS[rem - 10]);
  } else {
    const t = Math.floor(rem / 10);
    const u = rem % 10;
    if (t) parts.push(TENS[t]);
    if (u) parts.push(feminine ? UNITS_F[u] : UNITS[u]);
  }
  return parts.join(' ');
}

function plural(n: number, forms: [string, string, string]): string {
  const m10 = n % 10;
  const m100 = n % 100;
  if (m10 === 1 && m100 !== 11) return forms[0];
  if (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) return forms[1];
  return forms[2];
}

// Сумма прописью: «Пятнадцать тысяч рублей 00 копеек»
export function amountInWords(amount: number): string {
  const rub = Math.floor(amount + 1e-9);
  const kop = Math.min(99, Math.round((amount - rub) * 100));
  const parts: string[] = [];
  const millions = Math.floor(rub / 1000000);
  const thousands = Math.floor((rub % 1000000) / 1000);
  const rest = rub % 1000;
  if (millions) parts.push(three(millions, false), plural(millions, ['миллион', 'миллиона', 'миллионов']));
  if (thousands) parts.push(three(thousands, true), plural(thousands, ['тысяча', 'тысячи', 'тысяч']));
  if (rest || parts.length === 0) parts.push(three(rest, false));
  const str =
    parts.join(' ') +
    ' ' +
    plural(rub, ['рубль', 'рубля', 'рублей']) +
    ' ' +
    String(kop).padStart(2, '0') +
    ' ' +
    plural(kop, ['копейка', 'копейки', 'копеек']);
  return str.charAt(0).toUpperCase() + str.slice(1);
}

// «15 000,00» — как в бланке-образце
const fmt = (n: number) => {
  const [i, d] = n.toFixed(2).split('.');
  return i.replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ',' + d;
};

const dateShort = (d: Date) =>
  `${String(d.getDate()).padStart(2, '0')}.${String(d.getMonth() + 1).padStart(2, '0')}.${d.getFullYear()}`;
const dateTitle = (d: Date) => `${d.getDate()} ${MONTHS_NOM[d.getMonth()]} ${d.getFullYear()} г.`;

/**
 * Счёт на оплату — точная копия бланка-образца (счёт We-130 от 01.11.2026):
 * логотип и предупреждение сверху (логотип тенанта из настроек брендинга),
 * образец платёжного поручения из 9 полей, подчёркнутый заголовок,
 * Поставщик/Покупатель строкой во всю ширину, таблица позиций, итоги с учётом
 * системы налогообложения («Без налога (НДС)» / НДС), сумма прописью и блок
 * подписей. «Действителен до» = дата счёта + 7 дней.
 */
export function buildInvoicePdf(
  r: {
    number: number;
    createdAt: Date;
    total: number;
    contact: { name: string; inn?: string | null; ogrn?: string | null; legalAddress?: string | null } | null;
    items: Array<{ quantity: number; price: number; sum: number; product: { name: string; unit: string } }>;
  },
  req: {
    fullName?: string;
    inn?: string;
    ogrn?: string;
    bankName?: string;
    bik?: string;
    account?: string;
    corrAccount?: string;
    legalAddress?: string;
    taxSystem?: string;
    vatRate?: string;
  } | null,
  logoPng?: Buffer | null,
) {
  const doc = new PDFDocument({ size: 'A4', margin: 50 });
  const fonts = resolveFonts();
  if (fonts) {
    doc.registerFont('reg', fonts.regular);
    doc.registerFont('bold', fonts.bold);
  }

  const L = 50;
  const R = 545;
  const W = R - L;

  const billDate = new Date(r.createdAt);
  const validUntil = new Date(billDate);
  validUntil.setDate(validUntil.getDate() + 7);

  const taxSystem = req?.taxSystem || 'osno';
  const vatRate = req?.vatRate || 'none';
  // НДС применяется только на ОСНО с выбранной ставкой; остальные режимы — «Без налога (НДС)»
  const vatPct = taxSystem === 'osno' && vatRate !== 'none' ? Number(vatRate) : 0;
  const subtotal = r.total;
  const vatSum = vatPct ? Math.round((subtotal * vatPct) / 100 * 100) / 100 : 0;
  const grand = Math.round((subtotal + vatSum) * 100) / 100;

  const v = (s: string | null | undefined) => (s && s.trim() ? s : '');

  // === Шапка: логотип тенанта (fallback — логотип платформы), предупреждение ===
  if (logoPng) doc.image(logoPng, L, 40, { height: 26 });
  else doc.image(Buffer.from(LOGO_PNG_BASE64, 'base64'), L, 40, { height: 26 });

  doc
    .font('reg')
    .fontSize(7)
    .fillColor('#111')
    .text(
      `Внимание! Счёт действителен до ${dateShort(validUntil)}. Оплата данного счёта означает согласие ` +
        'с условиями поставки товара. Уведомление об оплате обязательно, в противном случае не гарантируется ' +
        'наличие товара на складе. Товар отпускается по факту прихода денег на р/с Поставщика, самовывозом, ' +
        'при наличии доверенности и паспорта.',
      165,
      36,
      { width: 270, align: 'center', lineGap: 0.5 },
    );

  // === Образец заполнения платёжного поручения ===
  doc.font('bold').fontSize(10).text('Образец заполнения платёжного поручения', L, 104, { width: W, align: 'center' });

  // Геометрия платёжного поручения — как в бланке-образце:
  // левая секция (банк/ИНН/получатель/назначение), правая — БИК + два «Сч. №»,
  // ниже три строки «Вид оп.» / «Наз. пл.» / «Код» и подколонка «Срок плат.» / «Очер. плат.» / «Рез. поле».
  const X = 290; // граница левой/правой секций
  const XL = 335; // подпись | значение в правой секции
  const XM = 440; // вторая подколонка (Срок плат. / Очер. плат. / Рез. поле)
  const XR = 495; // её значения («5»)
  let y = 116;
  const yBankEnd = y + 32;
  const yInnEnd = yBankEnd + 16;
  const yPolEnd = yInnEnd + 20;
  const yNazEnd = yPolEnd + 20; // низ таблицы (88pt)
  const yBlock = yInnEnd; // правая секция: блок из 3 строк ниже двух «Сч. №»
  const blockRow = (yNazEnd - yBlock) / 3;

  doc.lineWidth(0.6).strokeColor('#111');
  // внешняя рамка и горизонтали
  doc.rect(L, y, W, yNazEnd - y).stroke();
  doc.moveTo(L, yBankEnd).lineTo(R, yBankEnd).stroke();
  doc.moveTo(L, yInnEnd).lineTo(R, yInnEnd).stroke();
  doc.moveTo(L, yPolEnd).lineTo(X, yPolEnd).stroke(); // только левая секция («Назначение платежа»)
  doc.moveTo(X, y + 16).lineTo(R, y + 16).stroke(); // БИК
  doc.moveTo(X, yBlock).lineTo(R, yBlock).stroke();
  doc.moveTo(X, yBlock + blockRow).lineTo(R, yBlock + blockRow).stroke(); // Наз. пл.
  doc.moveTo(X, yBlock + 2 * blockRow).lineTo(R, yBlock + 2 * blockRow).stroke(); // Код
  // вертикали
  doc.moveTo(X, y).lineTo(X, yNazEnd).stroke();
  doc.moveTo(120, yBankEnd).lineTo(120, yInnEnd).stroke(); // ИНН | КПП
  doc.moveTo(XL, y).lineTo(XL, yNazEnd).stroke();
  doc.moveTo(XM, yBlock).lineTo(XM, yNazEnd).stroke();
  doc.moveTo(XR, yBlock).lineTo(XR, yNazEnd).stroke();

  // подпись поля (мелкая)
  const labTop = (x: number, yy: number, s: string | null | undefined, wdt = 90) =>
    doc.font('reg').fontSize(6).fillColor('#333').text(s || '', x + 2, yy + 1.5, { width: wdt - 4, lineGap: 0 });

  // левая секция
  doc.font('reg').fontSize(10).fillColor('#111').text(v(req?.bankName) || '—', L + 2, y + 3, { width: X - L - 4, lineGap: 0 });
  labTop(L, y + 21, 'Банк получателя');
  labTop(L, yBankEnd, 'ИНН');
  doc.font('reg').fontSize(8.5).fillColor('#111').text(v(req?.inn) || '—', L + 2, yBankEnd + 7.5, { width: 66, lineGap: 0 });
  labTop(122, yBankEnd, 'КПП', X - 122);
  doc.font('reg').fontSize(9).fillColor('#111').text(v(req?.fullName) || '—', L + 2, yInnEnd + 2.5, { width: X - L - 4, lineGap: 0 });
  labTop(L, yInnEnd + 10.5, 'Получатель');
  doc.font('reg').fontSize(9.5).fillColor('#111').text(
    `Оплата заказа клиента №We-${r.number} от ${dateShort(billDate)}`,
    L + 2,
    yPolEnd + 2,
    { width: X - L - 4, lineGap: 0 },
  );
  labTop(L, yPolEnd + 12, 'Назначение платежа');

  // правая секция: БИК и счета (подпись сверху, значение под ней)
  labTop(X, y, 'БИК');
  doc.font('reg').fontSize(9).fillColor('#111').text(v(req?.bik) || '—', XL + 2, y + 4, { width: XM - XL - 2, lineGap: 0 });
  labTop(X, y + 16, 'Сч. №');
  doc.font('reg').fontSize(9).fillColor('#111').text(v(req?.corrAccount) || '—', XL + 2, y + 20, { width: R - XL - 4, lineGap: 0 });
  labTop(X, yBankEnd, 'Сч. №');
  doc.font('reg').fontSize(9).fillColor('#111').text(v(req?.account) || '—', XL + 2, yBankEnd + 4, { width: R - XL - 4, lineGap: 0 });
  // три строки «Вид оп.» / «Наз. пл.» / «Код» с подколонкой «Срок плат.» / «Очер. плат.» / «Рез. поле»
  const r1 = yBlock + blockRow;
  const r2 = yBlock + 2 * blockRow;
  labTop(X, yBlock, 'Вид оп.');
  doc.font('reg').fontSize(9).fillColor('#111').text('01', XL + 2, yBlock + 2, { width: XM - XL - 2, lineGap: 0 });
  labTop(XM, yBlock, 'Срок плат.', XR - XM);
  labTop(X, r1, 'Наз. пл.');
  labTop(XM, r1, 'Очер. плат.', XR - XM);
  doc.font('reg').fontSize(9).fillColor('#111').text('5', XR + 2, r1 + 2.2, { width: R - XR - 4, align: 'center', lineGap: 0 });
  labTop(X, r2, 'Код');
  doc.font('reg').fontSize(7.5).fillColor('#111').text(`3К261100WE ${String(r.number).padStart(10, '0')}`, XL + 2, r2 + 2.6, { width: XM - XL - 2, lineGap: 0 });
  labTop(XM, r2, 'Рез. поле', XR - XM);

  // === Заголовок ===
  y = yNazEnd + 14;
  doc.font('bold').fontSize(13).fillColor('#111').text(`Счёт на оплату № We-${r.number} от ${dateTitle(billDate)}`, L, y, { width: W, align: 'left' });
  y = doc.y + 6;
  doc.moveTo(L, y).lineTo(R, y).stroke();

  // === Поставщик / Покупатель ===
  y += 10;
  const joinParts = (parts: Array<string | null | undefined>) => parts.filter((x): x is string => !!x && !!x.trim()).join(', ');
  const supplier = joinParts([
    req?.fullName,
    req?.inn ? `ИНН ${req.inn}` : '',
    req?.ogrn ? `ОГРН ${req.ogrn}` : '',
    req?.legalAddress,
  ]);
  const buyer = joinParts([
    r.contact?.name,
    r.contact?.inn ? `ИНН ${r.contact.inn}` : '',
    r.contact?.ogrn ? `ОГРН ${r.contact.ogrn}` : '',
    r.contact?.legalAddress,
  ]);
  doc.font('bold').fontSize(9.5).text('Поставщик: ', L, y, { width: W, continued: true });
  doc.font('reg').text(supplier || '— заполните реквизиты в настройках (Системные → Реквизиты)');
  y = doc.y + 6;
  doc.font('bold').fontSize(9.5).text('Покупатель: ', L, y, { width: W, continued: true });
  doc.font('reg').text(buyer || '—');
  y = doc.y + 12;

  // === Таблица позиций ===
  const cols = [
    { x: L, w: 30, t: '№', align: 'center' as const },
    { x: L + 30, w: 290, t: 'Товары (работы, услуги)', align: 'center' as const },
    { x: L + 320, w: 75, t: 'Количество', align: 'center' as const },
    { x: L + 395, w: 50, t: 'Цена', align: 'center' as const },
    { x: L + 445, w: 50, t: 'Сумма', align: 'center' as const },
  ];
  const headerH = 18;
  const rowHeights = r.items.map((it) => {
    const h = doc.font('reg').fontSize(8.5).heightOfString(it.product.name, { width: cols[1].w - 8 });
    return Math.max(18, h + 7);
  });
  const tableH = headerH + rowHeights.reduce((a, b) => a + b, 0);

  if (y + tableH + 210 > doc.page.height) {
    doc.addPage();
    y = 50;
  }

  const hline = (yy: number) => { doc.moveTo(L, yy).lineTo(R, yy).stroke(); };
  const vline = (x: number, yFrom: number, yTo: number) => { doc.moveTo(x, yFrom).lineTo(x, yTo).stroke(); };
  hline(y);
  hline(y + headerH);
  let ry = y + headerH;
  rowHeights.forEach((h) => { hline(ry + h); ry += h; });
  vline(L, y, y + tableH);
  vline(R, y, y + tableH);
  cols.slice(1).forEach((c) => vline(c.x, y, y + tableH));

  doc.font('bold').fontSize(9).fillColor('#111');
  cols.forEach((c) => doc.text(c.t, c.x, y + 4, { width: c.w, align: c.align, lineGap: 0 }));

  ry = y + headerH;
  doc.font('reg').fontSize(8.5);
  r.items.forEach((it, i) => {
    const h = rowHeights[i];
    doc.text(String(i + 1), cols[0].x, ry + h / 2 - 4, { width: cols[0].w, align: 'center', lineGap: 0 });
    doc.text(it.product.name, cols[1].x + 4, ry + 3.5, { width: cols[1].w - 8, lineGap: 0.5 });
    doc.text(`${it.quantity} ${it.product.unit || 'шт'}`, cols[2].x, ry + h / 2 - 4, { width: cols[2].w, align: 'center', lineGap: 0 });
    doc.text(fmt(it.price), cols[3].x, ry + h / 2 - 4, { width: cols[3].w, align: 'center', lineGap: 0 });
    doc.text(fmt(it.sum), cols[4].x, ry + h / 2 - 4, { width: cols[4].w, align: 'center', lineGap: 0 });
    ry += h;
  });

  // === Итоги (выравнивание вправо, как в бланке) ===
  let ty = y + tableH + 8;
  const tline = (label: string, value: string, bold = false) => {
    doc.font(bold ? 'bold' : 'reg').fontSize(9.5).fillColor('#111');
    doc.font(bold ? 'bold' : 'reg').fontSize(9.5);
    const lblW = doc.widthOfString(label);
    doc.font('reg').fontSize(9.5);
    const valW = doc.widthOfString(value);
    doc.font(bold ? 'bold' : 'reg').fontSize(9.5);
    doc.text(label, R - lblW - 10 - valW, ty, { lineGap: 0, continued: true });
    doc.font('reg').text(' ' + value, { lineGap: 0 });
    ty = doc.y + 2;
  };
  if (vatPct) {
    tline('Итого:', fmt(subtotal));
    tline(`В том числе НДС ${vatPct}%:`, fmt(vatSum));
    tline('Всего к оплате:', fmt(grand), true);
  } else {
    tline('Итого:', fmt(subtotal));
    tline('Без налога (НДС)', '-');
  }

  // === Сумма прописью ===
  ty += 6;
  doc.font('reg').fontSize(9.5).fillColor('#111');
  const grandForWords = vatPct ? grand : subtotal;
  doc.text(`Всего наименований ${r.items.length}, на сумму ${fmt(grandForWords)} RUB`, L, ty, { width: W, lineGap: 0 });
  ty = doc.y + 2;
  doc.font('bold').text(amountInWords(grandForWords));
  ty = doc.y + 8;
  doc.moveTo(L, ty).lineTo(R, ty).stroke();

  // === Подписи ===
  ty += 14;
  const signRows = ['Генеральный директор', 'Бухгалтер'];
  signRows.forEach((label, idx) => {
    doc.font('reg').fontSize(9).text(label, L, ty, { width: 120, lineGap: 0 });
    // линия подписи
    doc.moveTo(185, ty + 12).lineTo(345, ty + 12).stroke();
    doc.font('reg').fontSize(6.5).fillColor('#333').text('подпись', 185, ty + 14, { width: 160, align: 'center', lineGap: 0 });
    // линия расшифровки
    doc.moveTo(375, ty + 12).lineTo(R, ty + 12).stroke();
    doc.font('reg').fontSize(6.5).fillColor('#333').text('расшифровка подписи', 375, ty + 14, { width: R - 375, align: 'center', lineGap: 0 });
    ty += 30;
  });

  return doc;
}
